input.command:
$paths = @(
    "$env:ProgramFiles",
    "${env:ProgramFiles(x86)}",
    "$env:LOCALAPPDATA",
    "$env:APPDATA",
    "D:\"
)
foreach ($p in $paths) {
    if (Test-Path $p) {
        Get-ChildItem -Path $p -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'uu|UURemote' } | ForEach-Object { "$($_.FullName)" }
    }
}

Write-Output "---进程列表---"
Get-Process | Where-Object { $_.ProcessName -match 'GameViewer' } | Select-Object Id, ProcessName, MainWindowTitle, StartTime | Format-Table -AutoSize

Write-Output "---应用程序错误日志(最近20条,不做消息过滤)---"
try {
    Get-WinEvent -FilterHashtable @{LogName='Application'; Level=2,3} -MaxEvents 100 -ErrorAction Stop |
        Where-Object { $_.ProviderName -match 'GameViewer|.NET|Application Error' -or $_.Message -match 'GameViewer' } |
        Select-Object TimeCreated, ProviderName, Id -First 10 | Format-Table -AutoSize
} catch {
    Write-Output "无匹配日志或查询出错: $($_.Exception.Message)"
}

$events = Get-WinEvent -FilterHashtable @{LogName='Application'; Id=1000} -MaxEvents 10 -ErrorAction SilentlyContinue
foreach ($e in $events) {
    if ($e.Message -match 'GameViewer') {
        Write-Output "=== $($e.TimeCreated) ==="
        Write-Output $e.Message
        Write-Output ""
    }
}

$candidates = @(
    "$env:LOCALAPPDATA\GameViewer",
    "$env:APPDATA\GameViewer",
    "$env:LOCALAPPDATA\uu",
    "$env:APPDATA\uu"
)
foreach ($c in $candidates) {
    if (Test-Path $c) { Write-Output "残留: $c" }
}
Write-Output "检查完毕"
